// the list #direction and the checkbox #agree. Each field has its own error element:
// #name-error, #email-error, #age-error, #direction-error, #agree-error
// (the error id is written in the field's aria-describedby attribute).
// The button is #submit-btn, the success message is #form-message.
//
// The practice "server" already exists:
// sendApplication(data, onSuccess) - takes the data and after 1 second
// calls the function onSuccess (as if the server replied "accepted").

// 1. Save the jQuery objects of the form, fields, button and message in constants

// 2. function showError($field, text) - text into the error element + aria-invalid="true"
//    function clearError($field) - empty text + remove aria-invalid

// 3. function validateForm() - checks ALL fields and returns true / false:
//    the name after trim() is not empty ("Enter your name") and not shorter than 2 ("Name - at least 2 characters");
//    the email contains @ ("Enter an email with the @ symbol");
//    the age is a number from 14 to 60 ("Age - a number from 14 to 60");
//    a track is selected ("Choose a track");
//    the checkbox is checked ("Confirm that you agree to the rules")

// 4. $form.on("submit", ...): preventDefault, clear #form-message, validate;
//    on success - block the button with the text "Sending...",
//    sendApplication($form.serializeArray(), function) and inside the function:
//    the message "Thank you, Anna! You are signed up for: Web development.", reset the form,
//    the button is available again with the text "Sign up"

task.setup:
const sentData = [];
let pendingCallbacks = [];
function sendApplication(data, onSuccess) {
    sentData.push(data);
    pendingCallbacks.push(onSuccess);
    setTimeout(finishSending, 1000);
}
function finishSending() {
    const callbacks = pendingCallbacks;
    pendingCallbacks = [];
    callbacks.forEach((callback) => callback());
}
